(141, '_transient_piensa_marketplace_config', 'a:2:{s:4:\"data\";a:1:{s:4:\"data\";a:10:{s:10:\"en_plugins\";s:1766:\"[{    \"slug\":\"ionos-essentials\",    \"custom\":true,    \"name\":\"Essentials\",    \"description\":\"The essentials plugin provides Piensa hosting specific functionality.\",    \"custom_icon_url\":\"https://s3-de-central.profitbricks.com/web-hosting/piensa/live/assets/icon-essentials-48px.svg\",    \"custom_info_url\":\"https://github.com/IONOS-WordPress/ionos-wordpress/releases/download/%40ionos-wordpress%2Flatest/ionos-essentials-info.json\"},   {\"slug\":\"woocommerce-german-market-light\",\"custom\":true,\"name\":\"Woocommerce German Market Light\",\"description\":\"Extension for WooCommerce providing features for legal compliance when your e-commerce business is based in Germany or Austria.\",\"custom_icon_url\":\"https://web-hosting.s3-eu-central-1.ionoscloud.com/ionos/live/assets/german_market_logo.png\",\"custom_info_url\":\"https://s3-de-central.profitbricks.com/web-hosting/ionos-group/woocommerce-german-market-light.info.json\"},   {      \"slug\":\"antispam-bee\"   },   {      \"slug\":\"limit-login-attempts-reloaded\"   },   {      \"slug\":\"jetpack\"   },   {      \"slug\":\"cachify\"   },   {      \"slug\":\"broken-link-checker\"   },   {      \"slug\":\"contact-form-7\"   },   {      \"slug\":\"regenerate-thumbnails-advanced\"   },   {      \"slug\":\"embed-privacy\"   },   {      \"slug\":\"statify\"   },   {      \"slug\":\"lazy-loading-responsive-images\"   },   {      \"slug\":\"woocommerce\"   },   {      \"slug\":\"wordpress-seo\"   },   {      \"slug\":\"avatar-privacy\"   },   {      \"slug\":\"two-factor\"   },   {      \"slug\":\"webmention\"   },   {      \"slug\":\"podlove-podcasting-plugin-for-wordpress\"   },   {      \"slug\":\"wp-maintenance-mode\"   },   {      \"slug\":\"wordfence\"   },   {      \"slug\":\"duplicate-post\"   },   {      \"slug\":\"google-analytics-for-wordpress\"   },   {      \"slug\":\"autopt