(143, '_transient_piensa_journey_config', 'a:2:{s:4:\"data\";a:1:{s:4:\"data\";a:4:{s:10:\"en_journey\";s:56415:\"{     \"dashboard\": [         {             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Welcome\",                     \"htmlContent\": \"… to Piensa Journey!\\n\\nHere, you’ll find an introductory tour of your WordPress website, showing you all the essential areas and features of WordPress step-by-step.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Target Audience\",                     \"htmlContent\": \"Piensa Journey is aimed especially at users with little or no previous experience with WordPress.\\nYou can stop the tour at any time and continue it at a later date.\"                 },                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2016/11/22/19/24/archive-1850170_960_720.jpg\",                     \"headline\": \"Navigation\",                     \"htmlContent\": \"In addition to the controls in this box, there are other controls in the top navigation bar.\\n\\nYou can jump to the previous and next step, quit Piensa Journey, or start autoplay.\"                 },                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2016/11/22/19/24/archive-1850170_960_720.jpg\",                     \"headline\": \"Here we go!\",                     \"htmlContent\": \"After this short introduction, we hope you enjoy Piensa Journey!\"                 }             ]         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"The Dashboard is your central hub. This is where all the threads come together. For example, you’ll be informed about news in the WordPress universe here, and it will also show you the latest changes.\"         },         {             \"htmlSelector\": \"#adminmenu\",             \"type\": \"focus\",             \"htmlContent\": \"The menu contains the individual sections available to you for editing your WordPress website. Throughout this tour, we will detail some of these areas.\"         },         {             \"htmlSelector\": \"#menu-posts\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can create, edit or delete posts.\\n click on the menu item if you want to learn more about it.\"         },         {             \"htmlSelector\": \"#menu-media\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"Here you can upload, edit or delete media (e.g.&nbsp;images).\\n click on the menu item if you want to learn more about it.\"         },         {             \"htmlSelector\": \"#menu-pages\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can create new pages and edit or delete existing ones.\\n\\nDo you want to know more about this section? Then click on this menu item now.\\n\\nAlternatively, you can continue as before.\"         },         {             \"htmlSelector\": \"#menu-comments\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can view, edit or even remove created comments.\\n\\nDo you want to learn more about this section? Then click on this menu item now.\\n\\nAlternatively, you can continue as usual.\"         },         {             \"htmlSelector\": \"#menu-appearance\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can change the appearance of your website. You also can install new free themes from the WordPress.org directory.\\n\\nWould you like to learn more about this section? Then click on this menu item now.\\n\\nAlternatively, you can continue as usual.\"         },         {             \"htmlSelector\": \"#menu-plugins\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can view the plugins active on your website, install new ones or delete or deactivate existing ones.\\n\\nDo you want to know more about this section? Then click on this menu item now.\\n\\nAlternatively, you can continue as usual.\"         },         {             \"htmlSelector\": \"#menu-users\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can create new users, delete existing ones or change permissions.\\n\\nDo you want to learn more about this section? Then click on this menu item now.\\n\\nAlternatively, you can continue as before.\"         },         {             \"htmlSelector\": \"#menu-tools\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can find handy tools for your website.\\n\\nDo you want to know more about this section? Then click on this menu item now.\\n\\nAlternatively, you can continue as usual.\"         },         {             \"htmlSelector\": \"#menu-settings\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can view and change the settings of your instance.\\n\\nDo you want to know more about this section? Then click on this menu item now.\\n\\nAlternatively, you can continue as usual.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"## End\\nYour tour ends at this point. You can start it over at any time or view only individual sections of the tour.\"         }     ],     \"edit-post\": [         {             \"htmlSelector\": \"#piensa-journey-guide\",             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2017/05/12/08/29/coffee-2306471_960_720.jpg\",                     \"headline\": \"Overview\",                     \"htmlContent\": \"You are in the posts overview. From here, you can create, edit or delete posts.\"                 },                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2016/11/22/19/24/archive-1850170_960_720.jpg\",                     \"headline\": \"What are posts?\",                     \"htmlContent\": \"These are \\\\\\\"classic\\\\\\\" blog posts that are displayed in chronological order on a post page. Posts can be categorized and tagged. In addition, you have the option to allow comments.\"                 }             ]         },         {             \"htmlSelector\": \"#posts-filter thead\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"You can change the ordering of the list by clicking on a column title. However, not all of them can be clicked, and the order does not affect the display order on the website.\"         },         {             \"htmlSelector\": \".manage-column.column-comments\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In this column, you will get information about the number of released and pending comments.\\n\\nPending comments are comments that the post author has not yet released.\"         },         {             \"htmlSelector\": \".page-title-action\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"You can create a new post using this button.\\n\\n_Click the button to learn more about it._\"         },         {             \"htmlSelector\": \"#menu-posts a[href=\\\\\\\"edit-tags.php?taxonomy=category\\\\\\\"]\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can create, edit or delete categories.\\n\\n_Click on the menu item if you want to learn more about it._\"         },         {             \"htmlSelector\": \"#menu-posts a[href=\\\\\\\"edit-tags.php?taxonomy=post_tag\\\\\\\"]\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"In this section, you can create, edit or delete tags.\\n\\n_Click on the menu item if you want to learn more about it._\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"Now you’ve been given an overview of the post-management. _If you started the tour from the Dashboard, we’ll send you back there in the next step. Otherwise, the tour is finished._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"index\",             \"urlParams\": {                 \"tour_index\": 4             }         }     ],     \"post\": [         {             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2014/02/13/07/28/wordpress-265132_960_720.jpg\",                     \"headline\": \"Editor\",                     \"htmlContent\": \"You are in the editor. From here, you can edit and publish posts.\"                 },                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2017/03/03/13/56/key-2114046_960_720.jpg\",                     \"headline\": \"Visibility\",                     \"htmlContent\": \"In addition, there is an option to specify who can see the post. It is possible to share the post with everyone, no one or password protected.\"                 },                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2015/03/05/17/34/calendar-660670_960_720.jpg\",                     \"headline\": \"Planning\",                     \"htmlContent\": \"Additionally, you have the option to automatically publish the post at a specific time (date and time).\"                 }             ]         },         {             \"htmlSelector\": \".block-editor-writing-flow\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"This is the editor area. Here you will see the current content and title of the post.\"         },         {             \"htmlSelector\": \".editor-post-title__input\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In this field, you can specify the post’s title.\"         },         {             \"htmlSelector\": \".block-editor-block-list__layout\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In this section, you can add new blocks to the post such as paragraphs or images.\"         },         {             \"htmlSelector\": \".interface-interface-skeleton__sidebar\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In the sidebar, you can view and change the post’s settings.\\n\\nThis includes, for example, the categories, permalink or visibility.\"         },         {             \"htmlSelector\": \".edit-post-header\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In the toolbar, your options include:\\n\\n\\n* \\\\- Add blocks\\n* \\\\- Undo changes\\n* \\\\- Preview the post\\n* \\\\- Publish the post\\n* \\\\- Save the post\\n\"         },         {             \"htmlSelector\": \".block-editor-writing-flow\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"Now you have been given an overview of the post editor._If you did not start the tour from here, we will send you back to your last page in the next step. Otherwise, the tour is over for this section._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"edit\",             \"urlParams\": {                 \"tour_index\": 4             }         }     ],     \"page\": [         {             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2014/02/13/07/28/wordpress-265132_960_720.jpg\",                     \"headline\": \"editor\",                     \"htmlContent\": \"You are in the editor. From here, you can edit and publish pages.\"                 },                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2017/03/03/13/56/key-2114046_960_720.jpg\",                     \"headline\": \"Visibility\",                     \"htmlContent\": \"In addition, there is an option to specify who can see the page. It is possible to make the page available to anyone, keep it private, or secure it with a password.\"                 },                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2015/03/05/17/34/calendar-660670_960_720.jpg\",                     \"headline\": \"Planning\",                     \"htmlContent\": \"Additionally, you have the option to automatically publish the page at a specific time (date and time).\"                 }             ]         },         {             \"htmlSelector\": \".block-editor-writing-flow\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"This is the editor area. Here you will see the current content and title of the page.\"         },         {             \"htmlSelector\": \".editor-post-title__input\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In this field, you can specify the page’s title.\"         },         {             \"htmlSelector\": \".block-editor-block-list__layout\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In this section, you can add new blocks to the page such as paragraphs or images.\"         },         {             \"htmlSelector\": \".interface-interface-skeleton__sidebar\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In the sidebar, you can view and change the page’s settings.\\n\\nThis includes, for example, the permalink or the visibility.\"         },         {             \"htmlSelector\": \".edit-post-header\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"In the toolbar, your options include:\\n\\n\\n* \\\\- Add blocks\\n* \\\\- Undo changes\\n* \\\\- Preview the page\\n* \\\\- Publish the page\\n* \\\\- Save the page\\n\"         },         {             \"htmlSelector\": \".block-editor-writing-flow\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"Now you have been given an overview of the page editor.\\n\\n_If you did not start the tour from here, we will send you back to your last page in the next step. Otherwise, the tour is over for this section._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"index\",             \"urlParams\": {                 \"tour_index\": 6             }         }     ],     \"upload\": [         {             \"htmlSelector\": \"#piensa-journey-guide\",             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2016/06/27/07/30/elvis-presley-1482026_960_720.jpg\",                     \"headline\": \"Overview\",                     \"htmlContent\": \"You are in the media library. From here, you can manage your media, such as images.\"                 }             ]         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"All uploaded media will be displayed here, including media inserted directly into pages or posts.\"         },         {             \"htmlSelector\": \".page-title-action\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"Here, you can upload new media files. Alternatively, you can drag and drop the files directly to this page to upload it.\"         },         {             \"htmlSelector\": \".media-toolbar\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"You can switch between a list view and a grid view when viewing the media library. Also, you can filter the media by type and upload date.\"         },         {             \"type\": \"redirect\",             \"page\": \"index\",             \"urlParams\": {                 \"tour_index\": 5             }         }     ],     \"edit-page\": [         {             \"htmlSelector\": \"#piensa-journey-guide\",             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2017/01/07/15/07/bible-1960635_960_720.jpg\",                     \"headline\": \"Overview\",                     \"htmlContent\": \"You are in the page overview. From here, you can create, edit or delete pages.\"                 },                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2021/11/17/10/39/kangaroo-6803201_960_720.jpg\",                     \"headline\": \"What are pages?\",                     \"htmlContent\": \"Unlike blog posts, pages are used to create content that does not require a chronological order. Examples include masthead and about us page.\"                 }             ]         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",   