dline\": \"Overview\",                     \"htmlContent\": \"You are now in the comment overview. From here, you can edit or delete comments.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"What are comments?\",                     \"htmlContent\": \"This feature allows your visitors to comment on posts. Visitors can contribute in this way and enter into an exchange with you. If you don’t want to use this function, you can deactivate it.\"                 }             ]         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"Here you will see your website’s comments. In addition, you can get information about the author and information about which post the comment refers to.\"         },         {             \"htmlSelector\": \".comments thead\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"You can change the sort order of the list by clicking on a column title. However, not all of them can be clicked, and this does not affect the sorting on the website.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Now you’ve got a first impression of the comment overview.\\n\\n_If you started the tour from the Dashboard, we’ll send you back there in the next step. Otherwise, the tour is over for this section._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"index\",             \"urlParams\": {                 \"tour_index\": 7             }         }     ],     \"themes\": [         {             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Overview\",                     \"htmlContent\": \"We are now in the themes section. Here you can customize the design of your instance.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Theme Browser\",                     \"htmlContent\": \"Using the theme browser, you can install new free themes from the WordPress.org directory.\"                 }             ]         },         {             \"htmlSelector\": \".theme-browser.rendered\",             \"type\": \"focus\",             \"htmlContent\": \"This will display all your downloaded themes.\"         },         {             \"htmlSelector\": \".theme.active\",             \"type\": \"focus\",             \"htmlContent\": \"This is your current theme, as indicated by the label **Active** in front of the name.\"         },         {             \"htmlSelector\": \".theme.active .theme-actions\",             \"type\": \"focus\",             \"htmlContent\": \"With this button, you can customize the theme to your liking.\\n\\nFor example, you can customize the background or add a copyright notice to the footer.\"         },         {             \"htmlSelector\": \".theme.add-new-theme\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"Want to learn more about adding themes? Then click into this area now.\\n\\nAlternatively, you can continue as usual.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Now you’ve got an overview of the theme area.\\n\\n_If you started the tour from the Dashboard, we’ll send you back there in the next step. Otherwise, the tour for that area is finished._ 😊\"         },         {             \"type\": \"redirect\"