quí.\"         },         {             \"htmlSelector\": \".page-title-action\",             \"type\": \"focus\",             \"htmlContent\": \"Con este botón puedes instalar tu propio tema. El tema debe estar en formato .zip para poder subirlo.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"Ahora ya conoces el buscador de temas.\\n\\n_Si no empezaste la guía desde aquí, el siguiente paso te llevará a la página que visitaste anteriormente. De lo contrario, la guía de esta área termina aquí._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"themes\",             \"urlParams\": {                 \"tour_index\": 5             }         }     ],     \"plugins\": [         {             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Vista general\",                     \"htmlContent\": \"Aquí puedes ampliar las funciones de WordPress con plugins, así como ver un listado de los plugins ya instalados.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Buscador de plugins\",                     \"htmlContent\": \"Aquí puedes buscar y añadir plugins gratuitos a tu WordPress desde el directorio de WordPress.org.\"                 }             ]         },         {             \"htmlSelector\": \".wp-list-table.widefat.plugins\",             \"type\": \"focus\",             \"htmlContent\": \"Esta tabla muestra todos los plugins que ya se han descargado.\"         },         {             \"htmlSelector\": \".manage-column.column-name\",             \"type\": \"focus\",             \"htmlContent\": \"Esta columna muestra el nombre del plugin. Los plugins se pueden activar, desactivar o incluso eliminar de manera individual o en bloque.\"         },         {             \"htmlSelector\": \".manage-column.column-description\",             \"type\": \"focus\",             \"htmlContent\": \"En esta columna encontrarás una descripción del plugin, así como la versión instalada y el desarrollador.\"         },         {             \"htmlSelector\": \".page-title-action\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"Con este botón puedes añadir nuevos plugins.\\n\\nSi quieres saber más sobre cómo añadir plugins, haz clic aquí.\\n\\nSi no, puedes continuar con el siguiente elemento del menú.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"Ahora ya conoces el área de gestión de plugins.\\n\\n_Si empezaste la guía desde la interfaz del escritorio, el siguiente paso te llevará de nuevo allí. De lo contrario, la guía de esta área termina aquí._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"index\",             \"urlParams\": {                 \"tour_index\": 9             }         }     ],     \"plugin-install\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Desde aquí podrás buscar y añadir nuevos plugins a tu WordPress.\"         },         {             \"htmlSelector\": \".wp-filter\",             \"type\": \"focus\",             \"htmlContent\": \"En esta barra puedes elegir si buscar plugins o instalar plugins populares o recomendados.\"         },         {             \"htmlSelector\": \".plugin-card\",             \"type\": \"focus\",             \"htmlContent\": \"Cada plugin incluye información sobre el desarrollador, la función o funciones del plugin y cuándo se actualizó por última vez. También se muestra la valoración del mismo y si es compatible con su versión de WordPress.\"         },         {             \"htmlSelector\": \".install-now.button\",             \"type\": \"focus\",             \"htmlContent\": \"Con este botón puedes instalar, activar o actualizar el plugin.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"Ahora ya conoces el buscador de plugins.\\n\\n_Si no empezaste la guía desde aquí, el siguiente paso te llevará a la página que visitaste anteriormente. De lo contrario, la guía de esta área termina aquí._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"plugins\",             \"urlParams\": {                 \"tour_index\": 5             }         }     ],     \"users\": [         {             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Gestión de usuarios\",                     \"htmlContent\": \"Desde aquí puedes ver todas las cuentas de usuario que se han creado en tu sitio web.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Perfiles\",                     \"htmlContent\": \"Es posible asignar perfiles a los usuarios con diferentes permisos.\"                 }             ]         },         {             \"htmlSelector\": \".manage-column.column-username\",             \"type\": \"focus\",             \"htmlContent\": \"Esta columna muestra los nombres de los usuarios, así como sus fotos de perfil.\"         },         {             \"htmlSelector\": \".manage-column.column-role\",             \"type\"