ontent\": \"En el área dedicada a borrar datos personales puedes enviar una petición para eliminar los datos personales de un usuario por completo del sistema.\\n\\nHaz clic en este elemento del menú para saber más.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya conoces las herramientas de WordPress.\"         },         {             \"type\": \"redirect\",             \"page\": \"index\",             \"urlParams\": {                 \"tour_index\": 11             }         }     ],     \"export\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"En el área dedicada a exportar datos personales tienes la opción de exportar los datos del sitio web en formato .xml.\"         },         {             \"htmlSelector\": \"#export-filters fieldset\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes seleccionar qué datos quieres exportar. Se pueden exportar todos los datos o solo algunos.\"         },         {             \"htmlSelector\": \"#submit\",             \"type\": \"focus\",             \"htmlContent\": \"Para realizar la exportación, solo tienes que hacer clic en este botón (tienes que cerrar la guía primero).\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya sabes cómo se exportan datos desde WordPress.\"         },         {             \"type\": \"redirect\",             \"page\": \"tools\",             \"urlParams\": {                 \"tour_index\": 3             }         }     ],     \"site-health\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"En el área dedicada a la salud del sitio podrás comprobar el estado de tu WordPress.\"         },         {             \"htmlSelector\": \".site-health-progress-label\",             \"type\": \"focus\",             \"htmlContent\": \"Un adjetivo o una breve frase describe el estado de tu sitio web.\"         },         {             \"htmlSelector\": \".health-check-body.health-check-status-tab.hide-if-no-js\",             \"type\": \"focus\",             \"htmlContent\": \"El análisis se desglosa en información sobre la configuración y aspectos que requieren una mejora. En este caso, es importante solucionar los problemas críticos lo antes posible.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya conoces el área dedicada al análisis del estado de tu WordPress.\"         },         {             \"type\": \"redirect\",             \"page\": \"tools\",             \"urlParams\": {                 \"tour_index\": 4             }         }     ],     \"export-personal-data\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"En el área dedicada a la exportación de datos personales tienes la opción de exportar los datos de un usuario en formato .zip.\"         },         {             \"htmlSelector\": \".wp-privacy-request-form\",             \"type\": \"focus\",             \"htmlContent\": \"Para poder exportar datos personales, debes enviar primero una petición al administrador del sitio. La petición se envía directamente a la dirección de correo electrónico que introduzcas en el campo correspondiente.\"         },         {             \"htmlSelector\": \".wp-list-table.widefat.fixed.striped.table-view-list.privacy_requests\",             \"type\": \"focus\",             \"htmlContent\": \"En esta tabla puedes ver las peticiones que se han enviado y descargar los datos personales, así como cambiar el estado de las peticiones, reenviarlas o eliminarlas.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya sabes cómo exportar datos personales en WordPress.\"         },         {             \"type\": \"redirect\",             \"page\": \"tools\",             \"urlParams\": {                 \"tour_index\": 5             }         }     ],     \"erase-personal-data\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"En el área dedicada a borrar datos personales tienes la opción de borrar los datos personales de un usuario.\"         },         {             \"htmlSelector\": \".wp-privacy-request-form\",             \"type\": \"focus\",             \"htmlContent\": \"Cualquier usuario con acceso a tu WordPress puede enviar una petición para que se eliminen sus datos personales. Los administradores pueden generar peticiones de borrado de datos para los usuarios, siempre y cuando dispongan de la dirección de correo electrónico del usuario en cuestión.\"         },         {             \"htmlSelector\": \".wp-list-table.widefat.fixed.striped.table-view-list.privacy_requests\",             \"type\": \"focus\",             \"htmlContent\": \"En esta tabla puedes ver las peticiones que se han enviado y borrar los datos personales, así como cambiar el estado de las peticiones, reenviarlas o eliminarlas.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya sabes cómo borrar datos personales.\\n\\n_Si no empezaste la guía desde aquí, el siguiente paso te llevará a la página que visitaste anteriormente. De lo contrario, la guía de esta área termina aquí._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"tools\",             \"urlParams\": {                 \"tour_index\": 6             }         }     ],     \"options-general\": [         {             \"type\": \"guide\",             \"borderColor\": \"transparent\",             \"children\": [                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"Ajustes\",                     \"htmlContent\": \"Aquí puedes cambiar la configuración de tu WordPress.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"General\",                     \"htmlContent\": \"Esta área permite cambiar el título o nombre y la descripción de tu blog.\"                 }             ]         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Los ajustes generales de tu sitio web se modifican desde aquí.\"         },         {             \"htmlSelector\": \"#blogname\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes editar el título de tu sitio web.\"         },         {             \"htmlSelector\": \"#blogdescription\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes editar la descripción de tu sitio web.\"         },         {             \"htmlSelector\": \"#new_admin_email\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes editar la dirección de correo electrónico del administrador.\"         },         {             \"htmlSelector\": \"#users_can_register\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes establecer si los usuarios pueden registrarse.\"         },         {             \"htmlSelector\": \"#submit\",             \"type\": \"focus\",             \"htmlContent\": \"Haz clic en este botón para guardar los cambios.\"         },         {             \"htmlSelector\": \"#menu-settings\",             \"type\": \"focus\",             \"htmlContent\": \"Los ajustes están divididos en diferentes subcategorías a las que puedes acceder desde este menú.\"         },         {             \"htmlSelector\": \".wp-submenu.wp-submenu-wrap a[href^=options-general]\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora te encuentras en la categoría de ajustes generales.\"         },         {             \"htmlSelector\": \"a[href^=options-writing]\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"En la categoría para los ajustes de escritura puedes personalizar los ajustes de las entradas.\\n\\nHaz clic en este elemento del menú para saber más.\\n\\nSi no, puedes continuar con el siguiente elemento del menú.\"         },         {             \"htmlSelector\": \"a[href^=options-reading]\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"En la categoría para los ajustes de lectura puedes definir cómo se estructura o indexa tu página de inicio.\\n\\nHaz clic en este elemento del menú para saber más.\\n\\nDe lo contrario, también puedes continuar como de costumbre.\"         },         {             \"htmlSelector\": \"a[href^=options-discussion]\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"En la categoría para los ajustes de comentarios puedes definir los ajustes de los comentarios en tu WordPress.\\n\\nHaz clic en este elemento del menú para saber más.\\n\\nDe lo contrario, también puedes continuar como de costumbre.\"         },         {             \"htmlSelector\": \"a[href^=options-media]\",             \"type\": \"focus\",             \"isClickable\": false,             \"htmlContent\": \"En la categoría para los ajustes de medios puedes definir cómo se guardan los medios en tu sitio web.\\n\\nHaz clic en este elemento del menú para saber más.\\n\\nDe lo contrario, también puedes continuar como de costumbre.\"         },         {             \"htmlSelector\": \"a[href^=options-permalink]\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"En la categoría para los ajustes permanentes puedes definir la estructura de los enlaces permanentes de tu sitio.\\n\\nHaz clic en este elemento del menú para saber más.\\n\\nSi no, puedes continuar con el siguiente elemento del menú.\"         },         {             \"htmlSelector\": \"a[href^=options-privacy]\",             \"type\": \"focus\",             \"isClickable\": true,             \"htmlContent\": \"En la categoría para los ajustes de privacidad puedes definir la ubicación de la página de privacidad en el sitio web y en qué partes debe incluirse un enlace a la misma.\\n\\nHaz clic en este elemento del menú para saber más.\\n\\nSi no, puedes continuar con el siguiente elemento del menú.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya conoces el área dedicada a los ajustes de su instancia de WordPress.\\n\\n_Si empezaste la guía desde la interfaz del escritorio, el siguiente paso te llevará de nuevo allí. Si no, puedes continuar con el siguiente elemento del menú._ 😊\"         },         {             \"type\": \"redirect\",             \"page\": \"index\",             \"urlParams\": {                 \"tour_index\": 12             }         }     ],     \"options-writing\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes personalizar los ajustes de las entradas y los comentarios.\"         },         {             \"htmlSelector\": \"table:nth-of-type(1)\",             \"type\": \"focus\",             \"htmlContent\": \"La categoría y el formato de entrada por defecto de las entradas se puede personalizar en este área.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya sabes cómo cambiar los ajustes de escritura.\\n\\nSi no empezaste la guía desde aquí, el siguiente paso te llevará a la página que visitaste anteriormente.\\n\\nDe lo contrario, la guía de esta área termina aquí.\"         },         {             \"type\": \"redirect\",             \"page\": \"options-general\",             \"urlParams\": {                 \"tour_index\": 10             }         }     ],     \"options-reading\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes definir cómo se estructuran su página de inicio y sus entradas.\"         },         {             \"htmlSelector\": \"table tr:nth-of-type(1)\",             \"type\": \"focus\",             \"htmlContent\": \"Es posible especificar si la página de inicio debe mostrar una página estática o las últimas entradas publicadas.\"         },         {             \"htmlSelector\": \"table tr:nth-of-type(2)\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes definir el número máximo de entradas que se mostrarán por página.\"         },         {             \"htmlSelector\": \"table tr:nth-of-type(3)\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes definir el número máximo de entradas que se mostrarán en el tablero de publicaciones.\"         },         {             \"htmlSelector\": \"table tr:nth-of-type(4)\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes especificar qué contenido de las entradas se debe mostrar en el tablero de publicaciones.\"         },         {             \"htmlSelector\": \"table tr:nth-of-type(5)\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes definir si los motores de búsqueda pueden indexar tu sitio web, es decir, si las subpáginas de tu sitio web se deben mostrar en los motores de búsqueda.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya sabes cómo cambiar los ajustes de lectura.\\n\\nSi no empezaste la guía desde aquí, el siguiente paso te llevará a la página que visitaste anteriormente.\\n\\nDe lo contrario, la guía de esta área termina aquí.\"         },         {             \"type\": \"redirect\",             \"page\": \"options-general\",             \"urlParams\": {                 \"tour_index\": 11             }         }     ],     \"options-discussion\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes cambiar los ajustes de los comentarios y avatares.\"         },         {             \"htmlSelector\": \"table:nth-of-type(1)\",             \"type\": \"focus\",             \"htmlContent\": \"La parte superior de la página contiene todas las opciones de configuración de los comentarios y la moderación de los mismos.\"         },         {             \"htmlSelector\": \"table:nth-of-type(1) tr:nth-of-type(2)\",             \"type\": \"focus\",             \"htmlContent\": \"Por ejemplo, puedes marcar la casilla para que tus visitantes tengan que registrarse y acceder para poder comentar.\"         },         {             \"htmlSelector\": \"table:nth-of-type(2)\",             \"type\": \"focus\",             \"htmlContent\": \"La parte inferior de la página contiene las opciones de configuración de los avatares de los usuarios.\"         },         {             \"htmlSelector\": \"table:nth-of-type(2) tr:nth-of-type(1)\",             \"type\": \"focus\",             \"htmlContent\": \"Por ejemplo, puedes desactivar completamente los avatares.\"         },         {             \"htmlSelector\": \"table:nth-of-type(2) tr:nth-of-type(2)\",             \"type\": \"focus\",             \"htmlContent\": \"O solo permitir avatares para usuarios mayores de edad.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya sabes cómo cambiar los ajustes de los comentarios y avatares.\\n\\nSi no empezaste la guía desde aquí, el siguiente paso te llevará a la página que visitaste anteriormente.\\n\\nDe lo contrario, la guía de esta área termina aquí.\"         },         {             \"type\": \"redirect\",             \"page\": \"options-general\",             \"urlParams\": {                 \"tour_index\": 12             }         }     ],     \"options-permalink\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes definir los ajustes para los enlaces permanentes de tu WordPress.\"         },         {             \"htmlSelector\": \"table:nth-of-type(1)\",             \"type\": \"focus\",             \"htmlContent\": \"La estructura de una URL personalizada puede partir de un diseño propio o de uno predefinido.\"         },         {             \"htmlSelector\": \"table:nth-of-type(2)\",             \"type\": \"focus\",             \"htmlContent\": \"También es posible definir una estructura base personalizada para las URL de etiquetas o categorías. Dicha base aparece siempre delante de la categoría o etiqueta en la URL.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya sabes cómo cambiar los ajustes de los enlaces permanentes.\\n\\nSi no empezaste la guía desde aquí, el siguiente paso te llevará a la página que visitaste anteriormente.\\n\\nDe lo contrario, la guía de esta área termina aquí.\"         },         {             \"type\": \"redirect\",             \"page\": \"options-general\",             \"urlParams\": {                 \"tour_index\": 14             }         }     ],     \"options-privacy\": [         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes definir los ajustes de la página que incluye tu política de privacidad.\"         },         {             \"htmlSelector\": \"table:nth-of-type(1) tr:nth-of-type(1)\",             \"type\": \"focus\",             \"htmlContent\": \"Si lo deseas, puedes crear una nueva página de política de privacidad.\"         },         {             \"htmlSelector\": \"table:nth-of-type(1) tr:nth-of-type(2)\",             \"type\": \"focus\",             \"htmlContent\": \"O cambiar la página de tu sitio web que incluye la política de privacidad.\"         },         {             \"htmlSelector\": \"#wpcontent\",             \"type\": \"focus\",             \"htmlContent\": \"Ahora ya sabes cómo definir los ajustes de su política de privacidad.\\n\\nSi no empezaste la guía desde aquí, el siguiente paso te llevará a la página que visitaste anteriormente.\\n\\nDe lo contrario, la guía de esta área termina aquí.\"         },         {             \"type\": \"redirect\",             \"page\": \"options-general\",             \"urlParams\": {                 \"tour_index\": 15             }         }     ],     \"edit-category\": [         {             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2017/05/12/08/29/coffee-2306471_960_720.jpg\",                     \"headline\": \"Categorías\",                     \"htmlContent\": \"Aquí puedes crear, editar o eliminar categorías.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"¿Qué son las categorías?\",                     \"htmlContent\": \"Las categorías pueden utilizarse para agrupar las entradas por temas. Así, tus visitantes pueden filtrar las entradas según sus intereses.\"                 }             ]         },         {             \"htmlSelector\": \"#col-left\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes crear nuevas categorías. Debajo de cada campo encontrarás una breve descripción del uso del mismo.\"         },         {             \"htmlSelector\": \"#col-right\",             \"type\": \"focus\",             \"htmlContent\": \"Esta es la lista de todas las categorías creadas. Además del nombre, la descripción y el slug, también se incluye el número de entradas asignadas a cada categoría.\\n\\nPuedes cambiar el orden en el que se muestran las categorías al hacer clic en el título de una de las columnas. Cualquier cambio en el orden aquí no altera el orden en el que se muestran en tu sitio web.\"         },         {             \"type\": \"redirect\",             \"page\": \"edit\",             \"urlParams\": {                 \"tour_index\": 5             }         }     ],     \"edit-post_tag\": [         {             \"type\": \"guide\",             \"children\": [                 {                     \"imageUrl\": \"https://cdn.pixabay.com/photo/2017/05/12/08/29/coffee-2306471_960_720.jpg\",                     \"headline\": \"Etiquetas\",                     \"htmlContent\": \"Aquí puedes crear, editar o eliminar etiquetas.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"¿Qué son las categorías?\",                     \"htmlContent\": \"Las etiquetas tienen una función similar a la de las categorías, pero no pueden crearse de forma jerárquica. Más bien, estas se utilizan para describir el contenido de las entradas de forma más precisa.\"                 },                 {                     \"imageUrl\": \"https://s3-de-central.profitbricks.com/web-hosting/ionos/live/assets/journey/journey.png\",                     \"headline\": \"¿Para qué se utilizan?\",                     \"htmlContent\": \"Las etiquetas se pueden utilizar para describir el contenido de una entrada del blog con más detalle, como los hashtags en Twitter o Instagram. Los visitantes de tu sitio web pueden filtrar las entradas por etiquetas.\"                 }             ]         },         {             \"htmlSelector\": \"#col-left\",             \"type\": \"focus\",             \"htmlContent\": \"Aquí puedes crear nuevas etiquetas. Debajo de cada campo encontrarás una breve descripción del uso del mismo.\"         },         {             \"htmlSelector\": \"#col-right\",             \"type\": \"focus\",             \"htmlContent\": \"Esta es la lista de todas las etiquetas creadas. Además del nombre, la descripción y el slug, también se incluye el número de entradas asignadas a cada etiqueta.\"         },         {             \"type\": \"redirect\",             \"page\": \"edit\",             \"urlParams\": {                 \"tour_index\": 6             }         }     ] }\";s:12:\"en_interface\";s:498:\"{     \"name\": \"Piensa Solutions Journey\",     \"modal\": {         \"continue\": \"Continue\",         \"restart\": \"Restart\",         \"popup_title\": \"Do you want to continue your Journey?\",         \"popup_content\": \"You have already started a Journey, you can continue it now or start a new one.\",         \"popup_warning\": \"Restarting will overwrite your previous session.\"     },     \"settings\": {         \"visibility\": \"Show Journey\",         \"visibility_description\": \"Show Journey in Adminbar\"     } }\";s:12:\"es_interface\";s:600:\"{     \"name\": \"Piensa Solutions - Guía de primeros pasos\",     \"modal\": {         \"continue\": \"Continuar\",         \"restart\": \"Volver a empezar\",         \"popup_title\": \"¿Te gustaría continuar con la Guía?\",         \"popup_content\": \"Puedes continuar en el punto en el que lo dejaste anteriormente o volver a empezar.\",         \"popup_warning\": \"Si decides volver a empezar, se perderá el progreso alcanzado en tu guía.\"     },     \"settings\": {         \"visibility\": \"Mostrar progreso\",         \"visibility_description\": \"Mostrar Guía de primeros pasos en la barra de administración\"     } }\";}}s:12:\"last_checked\";i:1763730497;}', 'yes');
